Console.WriteLine(D.F(1_000_000m, false));
Console.WriteLine(D.F(2_000_000m, true));
Console.WriteLine(D.F(500_000m, true));

static class D
{
    // VIP -10%; đơn từ 1 triệu -5%
    public static decimal F(decimal total, bool vip)
    {
        var rate = 0m;
        if (vip) rate += 0.10m;
        if (total > 1_000_000m) rate += 0.05m;
        return total * (1 - rate);
    }
}

